#!/usr/bin/env python3
"""
Round 209o (culprits-tiles-more), 15 October 2026.

- sun.py: objects orbiting the Sun (GCAT Heliocentric Register, CC BY), placed
  by NASA/JPL Horizons; the planets' places and paths. Writes bodies/sun_*.json.
- gem_solar.py: Global Energy Monitor's Global Solar Power Tracker, from the
  owner's download in gem/solar/download/, to tiles/solar_gem.pmtiles.
- solar_companies.py: Wikipedia's List of photovoltaics companies, every
  company table, placed at headquarters from Wikidata; solar/companies.geojson.

Written only if it differs. Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {'scripts/sun.py': '', 'scripts/gem_solar.py': '', 'scripts/solar_companies.py': '', 'gem/solar/download/README.md': 'VXBsb2FkIEdsb2JhbCBFbmVyZ3kgTW9uaXRvcidzIEdsb2JhbCBTb2xhciBQb3dlciBUcmFja2VyIGRvd25sb2FkIGhlcmUgKHppcCBvciBzcHJlYWRzaGVldCwgYXMgaXQgY29tZXMpLgpUaGVuIHJ1biB0aGUgcmVmcmVzaCB3b3JrZmxvdyB3aXRoOiBnZW1fc29sYXIK'}

def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round209o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round209o_tiles: wrote {path}")
    if not changed:
        print("round209o_tiles: already applied")


if __name__ == "__main__":
    main()
